class _Header extends StatelessWidget{final PresentationState? s;final VoidCallback onChat;const _Header({required this.s,required this.onChat});@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);return Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Analysis Workspace',style:TextStyle(color:t.text,fontSize:23,fontWeight:FontWeight.w700)),const SizedBox(height:4),Text("Dharen's Home  •  One task, shared across Workspace and Chat",style:TextStyle(color:t.mutedText,fontSize:11))])),OutlinedButton.icon(onPressed:onChat,icon:const Icon(Icons.forum_outlined,size:16),label:const Text('Chat with Dharen'))]);}}
class _TaskHeader extends StatelessWidget{final PresentationState s;const _TaskHeader(this.s);@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);return Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:t.surfaceStrong,borderRadius:BorderRadius.circular(16),border:Border.all(color:t.border)),child:Wrap(spacing:28,runSpacing:12,children:[_item('TASK ID',s.taskId??'UNKNOWN',t),_item('TASK',s.task??'Unnamed task',t),_item('STATUS',s.taskState??'UNKNOWN',t),_item('CREATED',_time(s.taskCreatedAt),t),_item('LAST UPDATE',_time(s.taskUpdatedAt),t)]));}Widget _item(String label,String value,CriterivoxTheme t)=>SizedBox(width:145,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:TextStyle(color:t.mutedText,fontSize:8,fontWeight:FontWeight.w700,letterSpacing:.8)),const SizedBox(height:5),Text(value,overflow:TextOverflow.ellipsis,maxLines:2,style:TextStyle(color:t.text,fontSize:11,fontWeight:FontWeight.w700))]));String _time(String? raw){if(raw==null)return 'Not available';final parsed=DateTime.tryParse(raw);return parsed==null?raw:parsed.toLocal().toString().split('.').first;}}
class _FoundationBanner extends StatelessWidget{final PresentationState s;const _FoundationBanner(this.s);@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);final id=s.foundationId;return Container(width:double.infinity,padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:t.surface,borderRadius:BorderRadius.circular(14),border:Border.all(color:t.primary.withValues(alpha:.45))),child:Row(children:[Icon(Icons.inventory_2_rounded,color:t.primary,size:21),const SizedBox(width:10),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(id==null?'No S5 DataFoundation attached':'S5 DataFoundation attached: $id',style:TextStyle(color:t.text,fontSize:12,fontWeight:FontWeight.w700)),const SizedBox(height:4),Text(id==null?'This task was created without a curated stewardship foundation.':'${s.foundationSourceCount??0} source(s) • ${s.foundationCandidateCount??0} candidate(s) • confirmation: ${s.foundationConfirmation??'unknown'}',style:TextStyle(color:t.mutedText,fontSize:9.5))]))]));}}
class _Kpis extends StatelessWidget{final PresentationState s;const _Kpis(this.s);@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);final p=_progress(s.taskState);return Container(padding:const EdgeInsets.all(15),decoration:BoxDecoration(color:t.surface,borderRadius:BorderRadius.circular(14),border:Border.all(color:t.border)),child:Wrap(spacing:24,runSpacing:12,children:[_k('Overall Progress','${(p*100).round()}%',t),_k('Current Stage',s.taskState??'READY',t),_k('Data Items','${s.taskDataFields??0}',t),_k('Observations','${s.observations.length}',t),_k('Findings','${s.findings.length}',t),_k('References','${s.evidence.length}',t)]));}Widget _k(String a,String b,CriterivoxTheme t)=>SizedBox(width:120,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(a,style:TextStyle(color:t.mutedText,fontSize:8)),const SizedBox(height:5),Text(b,overflow:TextOverflow.ellipsis,style:TextStyle(color:t.text,fontSize:14,fontWeight:FontWeight.w700))]));}
double _progress(String? state){switch(state){case 'CREATED':return .05;case 'RECEIVED':return .15;case 'VALIDATING':return .30;case 'PROCESSING':return .50;case 'ANALYZING':return .70;case 'RESULT_READY':return .90;case 'COMPLETED':return 1;default:return 0;}}
class _DataContext extends StatelessWidget{final PresentationState s;const _DataContext(this.s);@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[_line('Data source',s.taskSource??'unknown',t),_line('Data fields','${s.taskDataFields??0}',t),_line('Context fields','${s.taskContextFields??0}',t),_line('Foundation',s.foundationId??'none',t),_line('References','${s.evidence.length}',t),_line('Task context',s.task??'not supplied',t)]);}Widget _line(String a,String b,CriterivoxTheme t)=>Padding(padding:const EdgeInsets.only(bottom:9),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(width:92,child:Text(a,style:TextStyle(color:t.mutedText,fontSize:9))),Expanded(child:Text(b,style:TextStyle(color:t.text,fontSize:10,fontWeight:FontWeight.w600)))]));}
class _ObservationChart extends StatelessWidget{final PresentationState s;const _ObservationChart(this.s);@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);final values=[s.observations.length,s.findings.length,s.evidence.length];final max=values.fold<int>(1,(a,b)=>a>b?a:b);return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[SizedBox(height:150,child:Row(crossAxisAlignment:CrossAxisAlignment.end,children:[for(var i=0;i<values.length;i++)Expanded(child:Padding(padding:const EdgeInsets.symmetric(horizontal:12),child:Column(mainAxisAlignment:MainAxisAlignment.end,children:[Text('${values[i]}',style:TextStyle(color:t.text,fontSize:12,fontWeight:FontWeight.w700)),const SizedBox(height:5),AnimatedContainer(duration:const Duration(milliseconds:300),height:90*values[i]/max,decoration:BoxDecoration(color:t.primary.withValues(alpha:.65),borderRadius:BorderRadius.circular(8))),const SizedBox(height:7),Text(['Observations','Findings','Evidence'][i],textAlign:TextAlign.center,style:TextStyle(color:t.mutedText,fontSize:8.5))])))])),const SizedBox(height:6),Text('Counts are derived from the authoritative runtime result, not generated chart values.',style:TextStyle(color:t.mutedText,fontSize:9))]);}}
class _Observations extends StatelessWidget{final PresentationState s;const _Observations(this.s);@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);if(s.observations.isEmpty)return Text('No observations have arrived yet.',style:TextStyle(color:t.mutedText,fontSize:10));return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[for(final o in s.observations.take(6))Padding(padding:const EdgeInsets.only(bottom:9),child:Text('• ${o['text']??''}',style:TextStyle(color:t.mutedText,fontSize:9.5,height:1.35)))]);}}
